import{_ as o,c as t,o as a,ag as r}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Sock Puppet Accounts/Phase4 Long Term Storage","description":"","frontmatter":{"title":"Sock Puppet Accounts/Phase4 Long Term Storage"},"headers":[],"relativePath":"privacy/sock-puppet-accounts-phase4-long-term-storage.md","filePath":"privacy/sock-puppet-accounts-phase4-long-term-storage.md","lastUpdated":null}'),s={name:"privacy/sock-puppet-accounts-phase4-long-term-storage.md"};function i(n,e,c,l,p,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="sock-puppet-accounts-phase4-long-term-storage" tabindex="-1">Sock Puppet Accounts/Phase4 Long Term Storage <a class="header-anchor" href="#sock-puppet-accounts-phase4-long-term-storage" aria-label="Permalink to &quot;Sock Puppet Accounts/Phase4 Long Term Storage&quot;">​</a></h1><h2 id="principle" tabindex="-1">Principle <a class="header-anchor" href="#principle" aria-label="Permalink to &quot;Principle&quot;">​</a></h2><p><strong>Putting a sock into storage is unreliable at best.</strong> Not using an account for extended periods is not “normal” human behavior. Anticipate multiple security checks, so the basic principle is to stack up verification methods and take good notes. Good luck!</p><p>Return to <a href="/general/sock-puppet-accounts-creation.html">Puppet Creation Outline</a>.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><p><strong>Best Practice</strong>: The best practice is maintaining the sock with regular activity, but this requires more time and effort than one may assume.</p><p><strong>Take excellent notes</strong>: Log as much as possible about the last time the sock account was used, directly in KeePass or another note-taking method. Consider logging:</p><ul><li><p>Date-time</p></li><li><p>IP address/region</p></li><li><p>User-agent string</p></li><li><p>Case/topic used for</p></li></ul><p><strong>Ensure all accounts have a recovery e-mail address and non-SMS 2FA</strong>:</p><ul><li><p>Download “verification codes” or one-time log-in codes.</p></li><li><p>Backup 2FA secrets.</p></li><li><p><strong>Remove the original phone number as a recovery option if possible.</strong></p></li><li><p><strong>Consider porting your temporary phone number to Google Voice or another VoIP service (~$20)</strong>:</p><ul><li>Your accounts are already established, so you should be able to use a VoIP service to continue using the number.</li><li>This may not work well for high-value accounts (e.g., Facebook), as they often require uploading a government ID before allowing a ported number to be used long-term.</li></ul></li></ul><p><strong>Automation</strong>: Automating social media posts with a bot is an option, but it can make the account look suspicious to the platforms.</p><h3 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h3><ul><li><p><a href="https://support.google.com/voice/answer/1065667?hl=en" target="_blank" rel="noreferrer">Port your Google Voice number</a></p></li><li><p><a href="https://www.socialpilot.co/social-media-automation-tools" target="_blank" rel="noreferrer">13 Powerful Social Media Automation Tools to Use in 2024</a></p></li></ul><p>[Required]</p><p>[Teaming]</p>',15)])])}const m=o(s,[["render",i]]);export{h as __pageData,m as default};
